const thumb = a => `<div class="thumb">${equipment(a)}</div>`;
function toast(text, error=false) {
  const node=document.createElement('div');node.className=`toast${error?' error':''}`;node.innerHTML=`${icon(error?'info':'check')}<span>${esc(text)}</span>`;$('#toasts').append(node);setTimeout(()=>node.remove(),6500);
}
async function api(action, payload=null, headers={}) {
  if(typeof window.__KB_DEMO_API__==='function')return window.__KB_DEMO_API__(action,payload);
  const res=await fetch(`api.php?action=${encodeURIComponent(action)}`,{credentials:'same-origin',cache:'no-store',method:payload?'POST':'GET',headers:payload?{'Content-Type':'application/json','X-CSRF-Token':csrf||'',...headers}:headers,body:payload?JSON.stringify(payload):undefined});
  let data;try{data=await res.json();}catch{throw new Error('El servidor no respondió con datos válidos.');}
  if(!res.ok && !data.requiresLogin && !data.configurationRequired){if(res.status===409 && data.state){state=data.state;render();}throw new Error(data.error||'No se pudo completar la operación.');}
  return data;
}
function saveDemo() {if(mode==='demo'){try{localStorage.setItem(STORE_KEY,JSON.stringify(state));}catch{toast('No hay espacio para guardar. Exporta una copia desde Ajustes.',true);}}}
async function command(cmd, success, after=()=>{}) {
  if(busy)return;busy=true;document.body.classList.add('busy');
  try { const data=await api('command',{command:cmd,revision:state.revision,...(mode==='demo'?{state}:{})});state=data.state;saveDemo();selected=new Set([...selected].filter(id=>available(byId(id)||{})));closeModal(true);render();if(success)toast(success);after(); }
  catch(e){const error=$('.modal .form-error');if(error)error.textContent=e.message;else toast(e.message,true);}
  finally{busy=false;document.body.classList.remove('busy');}
}
async function bootstrap() {
  try {
    const data=await api('bootstrap');mode=data.mode;
    if(data.requiresLogin || data.needsSetup || data.configurationRequired){renderAuth(data);return;}
    user=data.user;csrf=data.csrf;state=data.state;
    if(mode==='demo'){try{const saved=JSON.parse(localStorage.getItem(STORE_KEY)||'null');if(saved?.version===1 && Array.isArray(saved.assets)&&Array.isArray(saved.kits)&&Array.isArray(saved.events)&&Array.isArray(saved.movements))state=saved;}catch{}}
    document.body.dataset.motion=localStorage.getItem('kb-motion')||'on';shell();render();
  }catch(e){$('#app').innerHTML=`<div class="auth-screen"><div class="auth-card panel panel-pad"><h1>Bodega sin conexión</h1><p>${esc(e.message)}</p>${btn('Volver a intentar','retry','','primary')}</div></div>`;}
}
function renderAuth(data) {
  const setup=data.needsSetup;
  $('#app').innerHTML=`<div class="auth-screen"><div class="auth-card"><div class="brand"><div class="brand-mark">K</div><div><div class="brand-name">KLANDESTINO</div><span class="brand-sub">BACKLINE MANAGER</span></div></div><div class="panel"><div class="eyebrow">Control de bodega</div><h1 class="gap">${setup?'Configura tu bodega':'Acceso del equipo'}</h1><p>${data.configurationRequired?esc(data.error):setup?'Crea el administrador de la instalación. Necesitas la clave definida en el servidor.':'Ingresa para coordinar inventario, salidas y retornos.'}</p>${data.configurationRequired?'':`<form data-form="${setup?'setup':'login'}">${setup?'<label>Nombre del administrador<input name="name" required maxlength="120" autocomplete="name"></label><label>Clave de instalación<input name="setupKey" type="password" required autocomplete="off"></label>':''}<label>Correo<input name="email" type="email" required maxlength="190" autocomplete="username"></label><label>Contraseña<input name="password" type="password" required ${setup?'minlength="12"':''} maxlength="128" autocomplete="${setup?'new-password':'current-password'}"></label>${setup?'<label class="check-label"><input name="seedDemo" type="checkbox">Cargar el inventario ficticio de demostración</label>':''}<div class="form-error" role="alert"></div><button class="btn primary">${setup?'Crear administrador':'Ingresar'} ${icon('arrow')}</button></form>`}</div><div class="footer-note">KLANDESTINO INC SPA · BACKLINE / KREW / PRODUCCIÓN</div></div></div>`;
}
const routes=[['dashboard','home','Dashboard'],['inventory','box','Inventario'],['kits','kit','Kits y componentes'],['events','calendar','Salidas y eventos'],['scan','qr','Escanear QR'],['maintenance','wrench','Mantenimiento'],['reports','chart','Reportes'],['settings','settings','Ajustes']];
function shell() {
  $('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#dashboard"><div class="brand-mark">K</div><div><div class="brand-name">KLANDESTINO</div><span class="brand-sub">BACKLINE MANAGER</span></div></a><div class="nav-label">CENTRO DE OPERACIONES</div><nav class="nav">${routes.map(([path,i,name])=>`<a href="#${path}" data-nav="${path}">${icon(i)}<span>${name}</span>${path==='events'?'<span class="nav-count" id="eventCount"></span>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="system-status"><i class="dot"></i>${mode==='demo'?'Demo operativa':'Bodega conectada'}</div><div class="sidebar-footer">BACKLINE / KREW / PRODUCCIÓN</div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Operaciones ${icon('arrow')} <strong id="breadcrumb"></strong></div><a href="#dashboard" class="mobile-brand"><div class="brand-mark">K</div><div class="brand-name">KLANDESTINO</div></a><div class="top-right"><div class="top-status"><i class="dot"></i><span>${mode==='demo'?'Guardado en este dispositivo':'Sincronizado con SQL'}</span></div><button class="icon-btn" data-action="refresh" title="Actualizar bodega" aria-label="Actualizar bodega">${icon('refresh')}</button><div class="top-identity">${esc(user.name)}<small>${mode==='demo'?'Demostración':({admin:'Administrador',operator:'Encargado',reader:'Consulta'})[user.role]}</small></div><div class="avatar">${esc(user.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div></div></header><div id="view"></div></main><nav class="mobile-nav">${[routes[0],routes[1],routes[2],routes[3],routes[4],routes[7]].map(([path,i,name])=>`<a href="#${path}" data-nav="${path}">${icon(i)}<span>${path==='kits'?'Kits':path==='events'?'Eventos':path==='settings'?'Más':name.replace('Escanear QR','Escanear')}</span></a>`).join('')}</nav>`;
}
const heading=(eyebrow,title,text,actions='')=>`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${esc(title)}</h1><p>${esc(text)}</p></div><div class="flex">${actions}</div></div>`;
function render() {
  if(!state)return;
  const [route='dashboard',id]=location.hash.slice(1).split('/');
  $$('.nav a,.mobile-nav a').forEach(a=>a.classList.toggle('active',a.dataset.nav===(route==='kit'?'kits':route==='event'?'events':route)));
  $('#breadcrumb').textContent=routes.find(r=>r[0]===(route==='kit'?'kits':route==='event'?'events':route))?.[2]||'Dashboard';
  $('#eventCount').textContent=state.events.filter(e=>e.items.some(i=>['reserved','out','missing'].includes(i.status))).length;
  const views={dashboard:dashboardView,inventory:inventoryView,kits:kitsView,kit:()=>kitView(id),events:eventsView,event:()=>eventView(id),scan:scanView,maintenance:maintenanceView,reports:reportsView,settings:settingsView};
  $('#view').innerHTML=`<div class="content">${mode==='demo'?`<div class="demo-strip">${icon('info')}<span>DEMO INTERACTIVA · Equipos y eventos ficticios. Los cambios se guardan en este navegador.</span></div>`:''}${(views[route]||dashboardView)()}<div class="footer-note">KLANDESTINO INC SPA · EQUIPOS EN ORDEN. ESCENARIOS LISTOS.</div></div>`;
  updateSelection();animateNumbers();
  if(route==='scan')$('#scanCode')?.focus({preventScroll:true});
}
function animateNumbers(){if(isReduced())return;$$('[data-number]').forEach(el=>{const target=+el.dataset.number,start=performance.now();const tick=t=>{const p=Math.min(1,(t-start)/320);el.textContent=Math.round(target*(1-(1-p)**3));if(p<1)requestAnimationFrame(tick);};requestAnimationFrame(tick);});}
function metrics(){const counts=['available','out','maintenance'].map(s=>state.assets.filter(a=>a.status===s).length);return `<div class="metrics">${[['Equipos individuales',state.assets.length,'box',`${state.kits.length} kits configurados · sin doble conteo`],['Disponibles',counts[0],'check','Listos para la próxima salida'],['En eventos',counts[1],'truck',`${state.assets.filter(a=>a.status==='reserved').length} piezas reservadas`],['En revisión',counts[2],'wrench',`${state.assets.filter(a=>a.status==='missing').length} faltantes por recuperar`]].map(([label,num,i,foot],n)=>`<div class="metric" style="--i:${n}"><div class="metric-top">${label}<span class="metric-icon">${icon(i)}</span></div><div class="metric-number" data-number="${num}">${num}</div><div class="metric-foot">${foot}</div></div>`).join('')}</div>`;}
function eventState(e){if(!e.items.length)return ['neutral','Sin equipos'];if(e.items.some(i=>i.status==='missing'))return ['missing','Con faltantes'];if(e.items.some(i=>i.status==='out'))return ['out','En evento'];if(e.items.some(i=>i.status==='reserved'))return ['reserved','En preparación'];return ['available','Completado'];}
function eventBadge(e){const [key,text]=eventState(e);return `<span class="badge ${key}">${text}</span>`;}
function activity(items=state.movements.slice(0,4)){return items.length?`<div class="activity">${items.map(m=>`<div class="activity-item"><div class="activity-icon">${icon(m.type==='dispatch'?'truck':m.type==='return'?'return':'check')}</div><div><strong>${esc(m.summary)}</strong><small>${esc(m.actor)} · ${date(m.at,{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}</small></div></div>`).join('')}</div>`:empty('Sin movimientos','El historial aparecerá cuando reserves o muevas equipos.');}
function dashboardView(){return `${heading('Centro de operaciones','KLANDESTINO BACKLINE','Todo el equipo. Cada pieza. Cada escenario.',btn(`${icon('plus')} Nueva salida`,'new-event','','primary',!canEdit()))}${metrics()}<div class="welcome-banner"><div><h2>Tu próxima salida empieza aquí.</h2><p>Arma un backline completo o elige exactamente las piezas que necesitas.</p></div><a class="btn" href="#kits">Ver kits ${icon('arrow')}</a></div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>Agenda de salidas</h2><a class="text-link" href="#events">Ver eventos ${icon('arrow')}</a></div>${state.events.length?`<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Evento / destino</th><th>Piezas</th><th>Estado</th></tr></thead><tbody>${[...state.events].sort((a,b)=>a.start.localeCompare(b.start)).slice(0,5).map(e=>`<tr><td class="mono">${date(e.start)}</td><td><a class="product-name" href="#event/${esc(e.id)}">${esc(e.name)}</a><small class="product-detail">${esc(e.place)}</small></td><td>${e.items.filter(i=>i.status!=='released').length}</td><td>${eventBadge(e)}</td></tr>`).join('')}</tbody></table></div>`:empty('Agenda despejada','Selecciona equipos para preparar la primera salida.')}</section><section class="panel"><div class="panel-head"><h2>Últimos movimientos</h2><a href="#reports" class="text-link">Historial ${icon('arrow')}</a></div>${activity()}</section></div><div class="dashboard-bottom"><section class="panel panel-pad"><div class="spread"><h2>Disponibilidad por categoría</h2>${icon('chart')}</div><div class="breakdown gap">${categories().slice(0,5).map(c=>{const total=state.assets.filter(a=>a.category===c).length,free=state.assets.filter(a=>a.category===c&&available(a)).length;return `<div class="breakdown-row"><div class="spread"><span>${esc(c)}</span><span class="muted">${free} / ${total}</span></div><div class="progress"><span style="width:${free/total*100}%"></span></div></div>`;}).join('')}</div></section><section class="panel panel-pad"><div class="spread"><h2>Identifica. Verifica. Mueve.</h2><span class="gold-text">${icon('qr')}</span></div><p class="gap">Escanea el QR de un gabinete, un tambor o un kit. Conoce su ubicación, responsable y último movimiento al instante.</p><a class="btn primary gap" href="#scan">${icon('qr')} Abrir escáner</a><div class="detail-grid"><div><small>INVENTARIO</small>QR único por pieza</div><div><small>KITS FLEXIBLES</small>Completos o por separado</div></div></section></div>`;}
const categories=()=>[...new Set(state.assets.map(a=>a.category))];
function inventoryView(){return `${heading('Inventario de bodega','Cada equipo, bajo control.','Busca, filtra y combina equipos para una salida.',`${btn(`${icon('print')} Etiquetas QR`,'labels')}${btn(`${icon('plus')} Nuevo equipo`,'new-asset','','primary',!canEdit())}`)}<div class="toolbar"><div class="search-input">${icon('search')}<input id="inventorySearch" type="search" placeholder="Equipo, código, marca o kit…" value="${esc(viewFilter)}" aria-label="Buscar equipos"></div><select id="categoryFilter" aria-label="Categoría"><option value="">Todas las categorías</option>${categories().map(c=>`<option ${c===categoryFilter?'selected':''}>${esc(c)}</option>`).join('')}</select><select id="statusFilter" aria-label="Estado"><option value="">Todos los estados</option>${Object.entries(statusNames).map(([v,t])=>`<option value="${v}" ${v===statusFilter?'selected':''}>${t}</option>`).join('')}</select></div><section class="panel"><div class="table-wrap"><table><thead><tr><th class="row-check"><input type="checkbox" id="selectAllInventory" aria-label="Seleccionar equipos disponibles" ${!canEdit()?'disabled':''}></th><th>Equipo</th><th class="hide-mobile">Código</th><th>Estado</th><th class="hide-mobile">Ubicación</th><th class="hide-mobile">Kit</th><th>QR</th></tr></thead><tbody id="inventoryBody">${inventoryRows()}</tbody></table></div><div class="list-footer"><span id="filteredCount">${filteredAssets().length} equipos</span><span>${state.assets.length} en inventario</span></div></section><div id="selectionBar"></div>`;}
function filteredAssets(){const q=viewFilter.toLocaleLowerCase('es');return state.assets.filter(a=>(!categoryFilter||a.category===categoryFilter)&&(!statusFilter||a.status===statusFilter)&&[a.name,a.code,a.brand,a.model,a.kitId||''].join(' ').toLocaleLowerCase('es').includes(q));}
function inventoryRows(){const assets=filteredAssets();return assets.length?assets.map(a=>`<tr><td class="row-check"><input type="checkbox" data-select="${esc(a.id)}" ${selected.has(a.id)?'checked':''} ${!available(a)||!canEdit()?'disabled':''} aria-label="Seleccionar ${esc(a.name)}"></td><td><div class="product-cell">${thumb(a)}<div><button class="text-link product-name" data-action="asset" ${idData(a.id)}>${esc(a.name)}</button><span class="product-detail">${esc(a.brand)} · ${esc(a.model)}</span></div></div></td><td class="mono hide-mobile">${esc(a.code)}</td><td>${badge(a.status)}</td><td class="hide-mobile"><small>${esc(a.location)}</small></td><td class="hide-mobile">${a.kitId?`<a class="text-link" href="#kit/${esc(a.kitId)}">${esc(a.kitId.replace('TAM-SCM-','Tama '))}</a>`:'<small>Individual</small>'}</td><td><button class="icon-btn" data-action="qr" ${idData(a.id)} aria-label="Ver QR de ${esc(a.name)}">${icon('qr')}</button></td></tr>`).join(''):`<tr><td colspan="7">${empty('No encontramos equipos','Prueba otro código, categoría o estado.')}</td></tr>`;}
function updateInventoryRows(){const body=$('#inventoryBody');if(body){body.innerHTML=inventoryRows();$('#filteredCount').textContent=`${filteredAssets().length} equipos`;}updateSelection();}
function kitStatus(k){const parts=kitParts(k.id),missing=k.expectedIds.filter(id=>!parts.some(a=>a.id===id)),free=parts.filter(available).length;return {parts,missing,free,complete:!missing.length&&parts.length>0&&parts.every(available)&&new Set(parts.map(a=>a.location)).size===1,assembled:k.assembled};}
function kitsView(){return `${heading('Kits inteligentes','Juntos o por separado.','Cada componente conserva su QR, ubicación e historial.',btn(`${icon('plus')} Crear kit`,'new-kit','','primary',!canEdit()))}<div class="kit-grid">${state.kits.map(k=>{const s=kitStatus(k);return `<a class="panel kit-card" href="#kit/${esc(k.id)}"><div class="kit-visual">${equipment({},true)}</div><div class="panel-pad"><div class="spread"><span class="eyebrow">${esc(k.id)}</span>${badge(s.complete?'available':'reserved')}</div><h2>${esc(k.name)}</h2><small>${esc(k.finish)}</small><div class="progress gap"><span style="width:${s.parts.length?s.free/s.parts.length*100:0}%"></span></div><div class="kit-meta"><span>${s.free}/${s.parts.length} piezas disponibles</span><span>${s.assembled?'Kit armado':'Piezas separadas'} ${icon('arrow')}</span></div></div></a>`;}).join('')||empty('Todavía no hay kits','Agrega equipos y selecciona sus piezas en inventario para crear el primer kit.')}</div><div class="notice gap">${icon('info')}Un kit agrupa equipos existentes: sus piezas se cuentan una sola vez. Puedes reservar todas juntas o repartirlas entre eventos.</div>`;}
function kitView(id){const k=kitById(id);if(!k)return empty('Kit no encontrado','Vuelve al inventario de kits.','<a class="btn" href="#kits">Ver kits</a>');const s=kitStatus(k);return `${heading('Gestión de kit',k.name,'Cada tambor y cada fierro se puede mover individualmente.',`<a class="btn" href="#kits">${icon('back')} Kits</a>${btn(icon('qr'),'qr',idData(k.id))}`)}<div class="kit-detail"><section class="panel"><div class="kit-visual">${equipment({},true)}</div><div class="kit-summary"><div class="eyebrow">${esc(k.id)}</div><h2>${esc(k.name)}</h2><p>${esc(k.finish)}</p><div class="notice gap ${s.complete?'success':''}">${icon(s.complete?'check':'info')}<span>${s.complete?(k.assembled?'Kit completo disponible':'Todas las piezas están disponibles. Puedes rearmar el kit.'):`${s.free} de ${s.parts.length} piezas disponibles${s.missing.length?`; ${s.missing.length} originales están en otra agrupación`:''}.`}</span></div><div class="detail-grid"><div><small>COMPONENTES</small><b>${s.parts.length} equipos individuales</b></div><div><small>AGRUPACIÓN</small><b>${k.assembled?'Kit armado':'Piezas separadas'}</b></div><div><small>LIBRES PARA SALIR</small><b>${s.free} disponibles</b></div><div><small>UBICACIONES</small><b>${new Set(s.parts.map(a=>a.location)).size}</b></div></div><div class="stack gap">${btn(`${icon(k.assembled?'split':'link')} ${k.assembled?'Separar kit':'Rearmar kit'}`,'kit-mode',idData(k.id),'',!canEdit()||(!k.assembled&&!s.complete))}${btn(`${icon('truck')} Reservar kit completo`,'select-kit',idData(k.id),'primary',!canEdit()||!s.complete)}</div></div></section><section class="panel"><div class="panel-head"><h2>Componentes del kit</h2><div class="segmented"><button data-action="kit-view" data-mode="all" class="${!kitByPiece?'active':''}">Vista kit</button><button data-action="kit-view" data-mode="piece" class="${kitByPiece?'active':''}">Por pieza</button></div></div><div class="panel-pad notice" style="margin:15px">${icon('info')}<span>${kitByPiece?'Selecciona exactamente lo que sale. El resto permanece en su ubicación.':'Usa «Reservar kit completo» para incluir todas las piezas. Cambia a «Por pieza» para dividir la salida.'}</span></div>${s.parts.map(a=>`<div class="part-item ${selected.has(a.id)?'selected':''}"><input type="checkbox" data-select="${esc(a.id)}" ${selected.has(a.id)?'checked':''} ${!kitByPiece||!available(a)||!canEdit()?'disabled':''} aria-label="Seleccionar ${esc(a.name)}">${thumb(a)}<div class="part-info"><button class="text-link" data-action="asset" ${idData(a.id)}><b>${esc(a.name)}</b></button><span class="mono">${esc(a.code)}</span></div>${badge(a.status)}<button class="icon-btn" data-action="qr" ${idData(a.id)} aria-label="QR de ${esc(a.name)}">${icon('qr')}</button></div>`).join('')}${s.missing.length?`<div class="panel-pad"><p>Originales fuera de este kit:</p>${s.missing.map(id=>`<button class="text-link" data-action="asset" ${idData(id)}>${esc(byId(id)?.name||id)} ${icon('arrow')}</button>`).join('<br>')}</div>`:''}</section></div><div id="selectionBar"></div>`;}
function updateSelection(){const valid=[...selected].filter(id=>byId(id)&&available(byId(id)));selected=new Set(valid);const bar=$('#selectionBar');if(bar)bar.innerHTML=valid.length?`<div class="sticky-selection"><span><b>${valid.length}</b> piezas seleccionadas${reserveTarget?` · ${esc(eventById(reserveTarget)?.name||'')}`:''}</span><div class="flex">${btn('Limpiar','clear-selection','','ghost small')}${!reserveTarget?btn('Crear kit','new-kit','','small'):''}${btn(`${icon('truck')} ${reserveTarget?'Reservar piezas':'Preparar salida'}`,'prepare','','primary small')}</div></div>`:'';$$('[data-select]').forEach(c=>{c.checked=selected.has(c.dataset.select);c.closest('.part-item')?.classList.toggle('selected',c.checked);});}
function eventsView(){return `${heading('Logística y coordinación','Salidas y eventos.','Reserva, verifica la carga y concilia cada devolución.',btn(`${icon('plus')} Nueva salida`,'new-event','','primary',!canEdit()))}<div class="event-grid">${[...state.events].sort((a,b)=>b.start.localeCompare(a.start)).map(e=>`<a class="panel event-card" href="#event/${esc(e.id)}"><div class="spread"><div class="date-tile">${date(e.start,{day:'2-digit'})}<small>${date(e.start,{month:'short'})}</small></div>${eventBadge(e)}</div><h2>${esc(e.name)}</h2><p class="flex">${icon('location')} ${esc(e.place)}</p><p class="flex" style="margin-top:8px">${icon('user')} ${esc(e.responsible)}</p><div class="event-card-footer spread"><small>${e.items.filter(i=>i.status!=='released').length} piezas · ${esc(e.service)}</small><span class="gold-text">${icon('arrow')}</span></div></a>`).join('')||empty('Tu agenda está lista','Selecciona equipos en inventario para crear la primera salida.')}</div>`;}
function eventView(id){const e=eventById(id);if(!e)return empty('Evento no encontrado','Revisa la lista de eventos.');const items=e.items.filter(i=>i.status!=='released');return `${heading('Orden de movimiento',e.name,e.place,`<a class="btn" href="#events">${icon('back')} Eventos</a>${btn(`${icon('print')} Manifiesto`,'manifest',idData(e.id))}`)}<div class="event-detail-top"><section class="panel panel-pad"><div class="spread"><h2>Información de la salida</h2>${eventBadge(e)}</div><div class="detail-grid"><div><small>RESPONSABLE / KREW</small><b>${esc(e.responsible)}</b></div><div><small>TRANSPORTE</small><b>${esc(e.vehicle||'Sin especificar')}</b></div><div><small>SALIDA PROGRAMADA</small><b>${date(e.start,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</b></div><div><small>DEVOLUCIÓN PROGRAMADA</small><b>${date(e.end,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</b></div></div></section><section class="panel panel-pad"><div class="spread"><h2>Control de carga y retorno</h2>${icon('truck')}</div><div class="detail-grid"><div><small>RESERVADOS</small><b>${items.filter(i=>i.status==='reserved').length} por despachar</b></div><div><small>FUERA DE BODEGA</small><b>${items.filter(i=>['out','missing'].includes(i.status)).length} pendientes</b></div><div><small>DEVUELTOS</small><b>${items.filter(i=>i.status==='returned').length} recibidos</b></div><div><small>FALTANTES</small><b>${items.filter(i=>i.status==='missing').length} por recuperar</b></div></div><div class="progress"><span style="width:${items.length?items.filter(i=>i.status==='returned').length/items.length*100:0}%"></span></div></section></div><div class="toolbar">${btn(`${icon('plus')} Añadir equipos`,'add-event-assets',idData(e.id),'',!canEdit())}${btn(`${icon('qr')} Verificar con QR`,'scan-event',idData(e.id))}<span class="muted" style="font-size:11px">Marca las piezas para registrar una salida o devolución parcial.</span></div><section class="panel"><div class="table-wrap"><table><thead><tr><th class="row-check"><input type="checkbox" id="selectAllEvent" aria-label="Seleccionar piezas activas del evento" ${!canEdit()?'disabled':''}></th><th>Equipo</th><th class="hide-mobile">Código</th><th>Movimiento</th><th class="hide-mobile">Observaciones</th></tr></thead><tbody>${items.map((it,index)=>{const a=byId(it.assetId);return a?`<tr><td class="row-check"><input type="checkbox" data-event-select="${esc(a.id)}" ${eventSelected.has(a.id)?'checked':''} ${!['out','reserved','missing'].includes(it.status)||!canEdit()?'disabled':''} aria-label="Seleccionar ${esc(a.name)} en evento"></td><td><div class="product-cell">${thumb(a)}<div><span class="product-name">${esc(a.name)}</span><span class="product-detail">${esc(a.kitId||a.brand)}</span></div></div></td><td class="mono hide-mobile">${esc(a.code)}</td><td>${it.status==='returned'?'<span class="badge available">Devuelto</span>':badge(it.status)}</td><td class="hide-mobile"><small>${esc(it.note||'—')}</small></td></tr>`:'';}).join('')||`<tr><td colspan="5">${empty('Aún sin equipos','Añade equipos disponibles desde inventario.')}</td></tr>`}</tbody></table></div></section><div class="toolbar gap" id="eventActions">${eventActions(e)}</div>`;}
function eventActions(e){const selectedItems=e.items.filter(i=>eventSelected.has(i.assetId)&&['reserved','out','missing'].includes(i.status));return `<small>${selectedItems.length} piezas seleccionadas</small>${btn(`${icon('truck')} Registrar salida`,'dispatch',idData(e.id),'primary',!canEdit()||!selectedItems.some(i=>i.status==='reserved'))}${btn(`${icon('return')} Registrar devolución`,'return',idData(e.id),'',!canEdit()||!selectedItems.some(i=>['out','missing'].includes(i.status)))}${btn('Liberar reserva','release',idData(e.id),'ghost',!canEdit()||!selectedItems.some(i=>i.status==='reserved'))}`;}
function scanView(){return `${heading('Identificación de activos','Escanea. Y sigue.','Lee el QR de una pieza o un kit con la cámara del teléfono.')}<div class="scan-layout"><section class="panel"><div class="camera-stage"><video id="camera" muted playsinline></video><div class="camera-frame">${icon('qr')}<div class="scan-line"></div></div><span class="scan-label" id="cameraLabel">Cámara lista para activar</span></div><div class="panel-pad flex wrap">${btn(`${icon('camera')} Activar cámara`,'camera','','primary')}${btn('Detener','stop-camera')}${btn('Leer imagen QR','scan-file')}<input type="file" id="scanFile" accept="image/*" class="hidden"></div><div class="scanner-help" id="scannerHelp">La cámara solo se usa para leer códigos. También puedes ingresar el código o cargar una foto del QR.</div></section><div class="stack"><section class="panel panel-pad"><h2>Ingreso manual</h2><p style="font-size:11px;margin:9px 0 17px">Código del equipo o del kit.</p><form data-form="lookup" class="flex"><input id="scanCode" name="code" placeholder="Ej. MAR-1960A-001" required maxlength="300" list="assetCodes" autocomplete="off" aria-label="Código de equipo"><button class="btn primary" aria-label="Buscar equipo">${icon('search')}</button></form><datalist id="assetCodes">${state.assets.map(a=>`<option value="${esc(a.code)}">${esc(a.name)}</option>`).join('')}${state.kits.map(k=>`<option value="${esc(k.id)}">${esc(k.name)}</option>`).join('')}</datalist></section><div id="scanResult"><section class="panel">${empty('Cada pieza tiene una historia.','Escanea un equipo para ver su estado, ubicación y movimientos.')}</section></div></div></div>`;}
function maintenanceView(){const assets=state.assets.filter(a=>a.status==='maintenance'||a.status==='missing');return `${heading('Revisión técnica','Vuelve a ponerlos en escena.','Daños, revisiones y faltantes identificados en los movimientos.')}<div class="event-grid">${assets.map(a=>`<section class="panel event-card"><div class="spread">${thumb(a)}${badge(a.status)}</div><h2>${esc(a.name)}</h2><p>${esc(a.note||'Pendiente de revisión.')}</p><div class="detail-grid"><div><small>CÓDIGO</small><span class="mono">${esc(a.code)}</span></div><div><small>UBICACIÓN</small>${esc(a.location)}</div></div><div class="gap">${a.status==='maintenance'?btn(`${icon('check')} Marcar revisado`,'maintenance-ready',idData(a.id),'primary',!canEdit()):`<a class="btn" href="#event/${esc(a.eventId)}">Abrir evento ${icon('arrow')}</a>`}</div></section>`).join('')||empty('Todo en orden','No hay equipos pendientes de revisión o recuperación.')}</div>`;}
function reportsView(){return `${heading('Información y trazabilidad','El historial no se pierde.','Quién movió cada pieza, a qué evento y en qué momento.',btn(`${icon('download')} Exportar inventario CSV`,'csv'))}<div class="report-grid"><section class="panel panel-pad"><div class="eyebrow">MOVIMIENTOS REGISTRADOS</div><div class="report-value">${state.movements.length}</div><p style="font-size:11px">Reservas, salidas, retornos y revisiones.</p></section><section class="panel panel-pad"><div class="eyebrow">PIEZAS FUERA DE BODEGA</div><div class="report-value">${state.assets.filter(a=>['out','missing'].includes(a.status)).length}</div><p style="font-size:11px">Incluye los faltantes hasta que se confirme su recuperación.</p></section></div><section class="panel gap"><div class="panel-head"><h2>Historial de movimientos</h2><small>${mode==='demo'?'Guardado en este navegador':'Registro SQL'}</small></div><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Operación</th><th>Responsable</th><th class="hide-mobile">Detalle / evidencia</th><th>Piezas</th></tr></thead><tbody>${state.movements.map(m=>`<tr><td class="mono">${date(m.at,{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}</td><td><span class="product-name">${esc(actionNames[m.type]||m.type)}</span><small class="product-detail">${esc(m.summary)}</small></td><td><small>${esc(m.actor)}</small></td><td class="hide-mobile"><small>${esc(m.note||'—')}</small>${m.photo?`<img class="image-proof" alt="Evidencia de devolución" src="${esc(m.photo)}" data-action="photo" ${idData(m.id)}>`:''}</td><td>${m.assetIds.length}</td></tr>`).join('')||'<tr><td colspan="5">Aún no hay movimientos.</td></tr>'}</tbody></table></div></section>`;}
function settingsView(){return `${heading('Tu bodega, a tu manera.','Ajustes y respaldo.','Controla la experiencia y conserva una copia de tus datos.')}<div class="report-grid"><section class="panel panel-pad"><div class="spread"><h2>Estado de la instalación</h2>${icon('shield')}</div><div class="detail-grid"><div><small>ENTORNO</small>${mode==='demo'?'Demostración interactiva':'Servidor PHP + SQL'}</div><div><small>USUARIO</small>${esc(user.name)}</div><div><small>DATOS</small>${mode==='demo'?'Solo este navegador':'Compartidos en SQL'}</div><div><small>REVISIÓN</small>${state.revision}</div></div><div class="notice gap">${icon('info')}<span>${mode==='demo'?'La demo permite probar todo con datos ficticios. En el hosting final, PHP y MySQL/MariaDB compartirán los movimientos entre encargados.':'Los cambios se confirman en una transacción SQL. Si otro encargado actualiza el inventario, verás una alerta para revisar la selección.'}</span></div>${mode!=='demo'?btn(`${icon('logout')} Cerrar sesión`,'logout','','gap'):''}</section><section class="panel panel-pad"><h2>Copias de datos</h2><p class="gap" style="font-size:12px">Descarga el inventario con kits, eventos e historial para conservar un respaldo.</p><div class="flex wrap gap">${btn(`${icon('download')} Exportar JSON`,'backup')}${btn('Inventario CSV','csv')}${mode==='demo'?btn('Importar copia demo','import-backup'):''}</div><input type="file" id="importBackup" accept="application/json,.json" class="hidden">${mode==='demo'?btn('Reiniciar demostración','reset-demo','','ghost gap'):''}</section><section class="panel panel-pad"><h2>Movimiento y fluidez</h2><p class="gap" style="font-size:12px">Transiciones rápidas al navegar, elegir piezas y abrir paneles. Puedes reducirlas en este dispositivo.</p><label class="check-label gap"><input type="checkbox" id="motionToggle" ${document.body.dataset.motion==='off'?'':'checked'}>Animaciones de interfaz</label></section><section class="panel panel-pad"><h2>Equipo de trabajo</h2><p class="gap" style="font-size:12px">Administrador: configuración y usuarios. Encargado: movimientos de bodega. Consulta: acceso de lectura.</p><div class="gap">${mode==='demo'?'<span class="badge neutral">Usuarios disponibles en la instalación SQL</span>':user.role==='admin'?btn(`${icon('user')} Gestionar usuarios`,'users'):'<small>Solicita acceso al administrador de la bodega.</small>'}</div></section></div>`;}

function openModal(title,html,{footer='',wide=false}={}) {
  overlayReturnFocus=document.activeElement;
  $('#overlay').innerHTML=`<div class="overlay-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close" aria-label="Cerrar">${icon('close')}</button></div>${html}${footer?`<div class="modal-foot">${footer}</div>`:''}</section></div>`;
  document.body.style.overflow='hidden';setTimeout(()=>$('input:not([type=checkbox]),select,button',$('.modal'))?.focus(),50);
}
function closeModal(force=false){if(busy&&!force)return;$('#overlay').innerHTML='';document.body.style.overflow='';overlayReturnFocus?.focus?.({preventScroll:true});returnPhoto='';}
function manifestList(ids){return `<div class="selected-manifest">${ids.map(id=>{const a=byId(id);return `<div><span>${esc(a?.name||id)}</span><span class="mono">${esc(id)}</span></div>`;}).join('')}</div>`;}
function showPrepare(){const ids=[...selected];if(!ids.length){toast('Selecciona al menos una pieza disponible.',true);return;}
  if(reserveTarget){const e=eventById(reserveTarget);openModal('Reservar para '+e.name,`<div class="modal-body"><p>${ids.length} piezas quedarán reservadas para este evento.</p>${manifestList(ids)}<div class="form-error gap"></div></div>`,{footer:btn('Cancelar','close')+btn('Confirmar reserva','confirm-reserve',idData(e.id),'primary')});return;}
  const localDate=offset=>{const d=new Date(Date.now()+offset*86400000);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,16);};
  openModal('Preparar nueva salida',`<form data-form="event"><div class="modal-body"><div class="notice">${icon('box')}<span>${ids.length} piezas seleccionadas. Se reservarán ahora; la salida física se confirma en el evento.</span></div><div class="form-grid gap"><label class="span2">Nombre del evento<input name="name" required maxlength="180" placeholder="Ej. Festival Metal · Escenario 2"></label><label class="span2">Destino / recinto<input name="place" required maxlength="200" placeholder="Ciudad y lugar"></label><label>Salida programada<input type="datetime-local" name="start" required value="${localDate(1)}"></label><label>Devolución programada<input type="datetime-local" name="end" required value="${localDate(2)}"></label><label>Responsable / Krew<input name="responsible" required maxlength="120" placeholder="Encargado de la carga"></label><label>Vehículo<input name="vehicle" maxlength="120" placeholder="Furgón / patente"></label><label class="span2">Servicio<select name="service"><option>Backline</option><option>Backline + Krew</option><option>Producción integral</option><option>Tour management</option></select></label></div>${manifestList(ids)}<div class="form-error gap" role="alert"></div></div><div class="modal-foot">${btn('Cancelar','close')}<button class="btn primary">${icon('check')} Confirmar reserva</button></div></form>`,{wide:true});
}
function showNewAsset(){openModal('Agregar equipo individual',`<form data-form="asset"><div class="modal-body"><div class="form-grid"><label class="span2">Nombre<input name="name" required maxlength="180" placeholder="Ej. Marshall 1960A 05"></label><label>Código único<input name="code" required pattern="[A-Za-z0-9][A-Za-z0-9_-]{2,59}" maxlength="60" placeholder="MAR-1960A-005"></label><label>Categoría<select name="category">${['Tambores','Fierros','Accesorios','Gabinetes','Cabezales','Micrófonos','Cables','Cases'].map(c=>`<option>${c}</option>`).join('')}</select></label><label>Marca<input name="brand" maxlength="80"></label><label>Modelo<input name="model" maxlength="100"></label><label>Número de serie<input name="serial" maxlength="100"></label><label>Ubicación<input name="location" value="Bodega A" required maxlength="120"></label></div><div class="form-error gap" role="alert"></div></div><div class="modal-foot">${btn('Cancelar','close')}<button class="btn primary">Guardar equipo</button></div></form>`);}
function showCreateKit(){if(!selected.size){reserveTarget=null;location.hash='inventory';toast('Selecciona las piezas y pulsa «Crear kit» en la barra inferior.');return;}openModal('Crear kit con la selección',`<form data-form="kit"><div class="modal-body"><div class="notice">${icon('info')}Las piezas conservan su QR e historial. Si pertenecían a otro kit, ese kit quedará incompleto.</div><div class="form-grid gap"><label class="span2">Nombre del kit<input name="name" required maxlength="180" placeholder="Ej. Backline Escenario 2"></label><label>Marca / agrupación<input name="brand" maxlength="80"></label><label>Descripción / acabado<input name="finish" maxlength="120"></label></div>${manifestList([...selected])}<div class="form-error gap"></div></div><div class="modal-foot">${btn('Cancelar','close')}<button class="btn primary">Crear kit</button></div></form>`);}
async function showQr(id){const a=byId(id)||kitById(id);if(!a)return;const svg=await QRCode.toString('KB:'+id,{type:'svg',errorCorrectionLevel:'M',margin:2,width:240});openModal('Etiqueta de equipo',`<div class="modal-body"><div class="qr-paper"><b>KLANDESTINO · BACKLINE</b>${svg}<b>${esc(id)}</b><small>${esc(a.name)}</small></div></div>`,{footer:btn(`${icon('print')} Imprimir`,'print')+btn('Cerrar','close')});}
async function showLabels(){const ids=selected.size?[...selected]:filteredAssets().map(a=>a.id);if(!ids.length){toast('No hay equipos para etiquetar.',true);return;}const labels=await Promise.all(ids.map(async id=>`<div class="qr-paper"><b>KLANDESTINO · BACKLINE</b>${await QRCode.toString('KB:'+id,{type:'svg',errorCorrectionLevel:'M',margin:2,width:160})}<b>${esc(id)}</b><small>${esc(byId(id).name)}</small></div>`));openModal(`${ids.length} etiquetas QR`, `<div class="modal-body"><div class="qr-print-grid">${labels.join('')}</div></div>`,{wide:true,footer:btn(`${icon('print')} Imprimir etiquetas`,'print')+btn('Cerrar','close')});}
function showAsset(id){const a=byId(id);if(!a)return;openModal(a.name,`<div class="modal-body"><div class="asset-hero">${equipment(a)}</div><div class="spread"><span class="mono">${esc(a.code)}</span>${badge(a.status)}</div><div class="detail-grid"><div><small>MARCA / MODELO</small>${esc(a.brand)} · ${esc(a.model)}</div><div><small>NÚMERO DE SERIE</small>${esc(a.serial||'Sin registrar')}</div><div><small>UBICACIÓN</small>${esc(a.location)}</div><div><small>AGRUPACIÓN</small>${a.kitId?esc(kitById(a.kitId)?.name):'Equipo individual'}</div></div>${a.note?`<div class="notice gap">${icon('info')}${esc(a.note)}</div>`:''}${a.eventId?`<div class="notice gap">${icon('calendar')}<a href="#event/${esc(a.eventId)}">${esc(eventById(a.eventId)?.name)} · ${esc(eventById(a.eventId)?.responsible)}</a></div>`:''}<div class="flex wrap gap">${btn(`${icon('qr')} Ver QR`,'qr',idData(id))}${available(a)?btn('Asignar a kit','assign-kit',idData(id),'',!canEdit()):''}${available(a)?btn('Enviar a revisión','maintenance-start',idData(id),'',!canEdit()):''}</div><h3 class="gap">Últimos movimientos de esta pieza</h3>${activity(state.movements.filter(m=>m.assetIds.includes(id)).slice(0,5))}</div>`,{footer:btn('Cerrar','close')});}
function showReturn(eventId,ids){const e=eventById(eventId);ids=ids||e.items.filter(i=>eventSelected.has(i.assetId)&&['out','missing'].includes(i.status)).map(i=>i.assetId);if(!ids.length)return;
  returnPhoto='';openModal('Registrar devolución',`<form data-form="return" data-event="${esc(eventId)}" data-ids="${esc(JSON.stringify(ids))}"><div class="modal-body"><p>${esc(e.name)} · ${ids.length} piezas seleccionadas</p><div class="form-grid gap"><label class="span2">Estado de las piezas seleccionadas<select name="condition" id="returnCondition"><option value="ok">Recibidas en buen estado</option><option value="damage">Recibidas con daño · enviar a revisión</option><option value="missing">No regresaron · reportar faltante</option></select></label><label class="span2">Observaciones<textarea name="note" maxlength="1500" placeholder="Describe daños, faltantes o detalles de la entrega"></textarea></label><label class="span2">Fotografía de evidencia (opcional)<input type="file" id="returnPhoto" accept="image/jpeg,image/png,image/webp"><small>La app reduce la foto antes de guardarla.</small></label><div id="photoPreview" class="span2"></div></div>${manifestList(ids)}<div class="form-error gap" role="alert"></div></div><div class="modal-foot">${btn('Cancelar','close')}<button class="btn primary">${icon('return')} Confirmar devolución</button></div></form>`);}
function confirmMovement(type,eventId){const e=eventById(eventId);const ids=e.items.filter(i=>eventSelected.has(i.assetId)&&i.status==='reserved').map(i=>i.assetId);if(!ids.length)return;openModal(type==='dispatch'?'Confirmar salida física':'Liberar reserva',`<div class="modal-body"><p>${type==='dispatch'?'Confirma que estas piezas fueron verificadas y cargadas.':'Estas piezas volverán a estar disponibles para otros eventos.'}</p>${manifestList(ids)}<div class="form-error gap"></div></div>`,{footer:btn('Cancelar','close')+btn(type==='dispatch'?'Confirmar salida':'Liberar piezas','confirm-movement',`data-type="${type}" data-event="${esc(eventId)}" data-ids="${esc(JSON.stringify(ids))}"`,'primary')});}
async function startCamera(){try{stopCamera();if(!navigator.mediaDevices?.getUserMedia)throw new Error('Este navegador no permite cámara aquí. Usa HTTPS, ingreso manual o una imagen QR.');stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:640},height:{ideal:480}},audio:false});const video=$('#camera');if(!video){stopCamera();return;}video.srcObject=stream;await video.play();$('#cameraLabel').textContent='Apunta al QR del equipo';const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d',{willReadFrequently:true});scanTimer=setInterval(()=>{if(!video.videoWidth||document.hidden)return;canvas.width=640;canvas.height=Math.round(video.videoHeight/video.videoWidth*640);ctx.drawImage(video,0,0,canvas.width,canvas.height);const image=ctx.getImageData(0,0,canvas.width,canvas.height),qr=jsQR(image.data,image.width,image.height,{inversionAttempts:'dontInvert'});if(qr){lookup(qr.data);stopCamera();}},120);}catch(e){$('#scannerHelp').textContent=e.name==='NotAllowedError'?'Permiso de cámara denegado. Puedes habilitarlo en el navegador o usar el ingreso manual.':e.message;toast('Puedes continuar con el código escrito o una imagen QR.',true);}}
function stopCamera(){if(scanTimer)clearInterval(scanTimer);scanTimer=null;if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;const v=$('#camera');if(v)v.srcObject=null;}
function lookup(raw){let code=raw.trim().replace(/^KB:/i,'').toUpperCase();if(code.startsWith('HTTPS://')){try{code=new URL(raw).searchParams.get('asset')?.toUpperCase()||code;}catch{}}
  const a=byId(code),k=kitById(code);if(!a&&!k){toast('Código no encontrado en este inventario.',true);return;}if($('#scanCode'))$('#scanCode').value=code;
  if(k){$('#scanResult').innerHTML=`<section class="panel scan-result"><div class="found-heading">${icon('check')} Kit identificado</div><div class="kit-visual">${equipment({},true)}</div><div class="panel-pad"><h2>${esc(k.name)}</h2><p class="gap">${kitParts(code).length} componentes · Cada pieza con QR propio.</p><a class="btn primary gap" href="#kit/${esc(code)}">Abrir kit ${icon('arrow')}</a></div></section>`;return;}
  if(reserveTarget){const e=eventById(reserveTarget);const it=e?.items.find(i=>i.assetId===a.id&&['reserved','out','missing'].includes(i.status));if(!it){toast('Este equipo no pertenece a la carga del evento seleccionado.',true);}else{const verified=verifiedForEvent.get(reserveTarget)||new Set();verified.add(a.id);verifiedForEvent.set(reserveTarget,verified);toast(`${a.name}: verificado para ${e.name}`);}}
  $('#scanResult').innerHTML=`<section class="panel scan-result"><div class="found-heading">${icon('check')} Componente identificado</div><div class="asset-hero">${equipment(a)}</div><div class="panel-pad"><div class="spread"><h2>${esc(a.name)}</h2>${badge(a.status)}</div><span class="mono" style="display:block;margin-top:9px">${esc(a.code)}</span><div class="detail-grid"><div><small>UBICACIÓN</small>${esc(a.location)}</div><div><small>KIT ASOCIADO</small>${esc(a.kitId||'Individual')}</div></div><div class="flex wrap gap">${available(a)?btn(`${icon('truck')} Seleccionar para salida`,'select-scanned',idData(a.id),'primary',!canEdit()):a.eventId?`<a class="btn primary" href="#event/${esc(a.eventId)}">Ver evento ${icon('arrow')}</a>`:''}${btn('Ver ficha','asset',idData(a.id))}</div>${reserveTarget&&eventById(reserveTarget)?`<a class="btn gap" href="#event/${esc(reserveTarget)}">Volver a ${esc(eventById(reserveTarget).name)}</a>`:''}</div></section>`;
}
async function readImageQR(file){if(!file||file.size>8000000){toast('Usa una imagen de menos de 8 MB.',true);return;}try{const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(1,1800/Math.max(bitmap.width,bitmap.height));canvas.width=bitmap.width*scale;canvas.height=bitmap.height*scale;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const image=ctx.getImageData(0,0,canvas.width,canvas.height),qr=jsQR(image.data,image.width,image.height);if(qr)lookup(qr.data);else toast('No se encontró un QR legible en la imagen.',true);}catch{toast('No pudimos leer esa imagen. Prueba con JPG o PNG.',true);}}
async function compressPhoto(file){if(!file)return;try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15000000)throw new Error('Usa JPG, PNG o WebP de hasta 15 MB.');const image=await createImageBitmap(file),scale=Math.min(1,800/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=image.width*scale;canvas.height=image.height*scale;canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);image.close();let q=.75;returnPhoto=canvas.toDataURL('image/jpeg',q);while(returnPhoto.length>190000&&q>.2){q-=.1;returnPhoto=canvas.toDataURL('image/jpeg',q);}if(returnPhoto.length>=200000)throw new Error('La foto es demasiado grande; prueba otra.');$('#photoPreview').innerHTML=`<img class="photo-preview" alt="Vista previa de evidencia" src="${returnPhoto}">`;}catch(e){returnPhoto='';toast(e.message,true);}}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function exportCSV(){const safe=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const rows=[['Código','Nombre','Marca','Modelo','Categoría','Estado','Ubicación','Kit','Evento','Serie'],...state.assets.map(a=>[a.code,a.name,a.brand,a.model,a.category,statusNames[a.status],a.location,a.kitId,a.eventId?eventById(a.eventId)?.name:'',a.serial])];download('klandestino-inventario.csv','\ufeff'+rows.map(r=>r.map(safe).join(';')).join('\r\n'),'text/csv;charset=utf-8');}
async function refresh(){if(mode==='demo'){render();toast('Datos locales actualizados.');return;}try{const data=await api('bootstrap');if(data.requiresLogin){closeModal();renderAuth(data);return;}state=data.state;render();toast('Bodega actualizada.');}catch(e){toast(e.message,true);}}

document.addEventListener('click', async ev=>{
  const el=ev.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;
  if(busy && !['print'].includes(action))return;
  try{switch(action){
    case 'retry':bootstrap();break;case 'refresh':refresh();break;case 'close':closeModal();break;
    case 'new-asset':showNewAsset();break;case 'new-kit':showCreateKit();break;case 'asset':showAsset(id);break;case 'qr':await showQr(id);break;case 'labels':await showLabels();break;
    case 'new-event':reserveTarget=null;if(selected.size)showPrepare();else{location.hash='inventory';toast('Selecciona las piezas o un kit para preparar la salida.');}break;
    case 'prepare':showPrepare();break;case 'clear-selection':selected.clear();reserveTarget=null;updateSelection();break;
    case 'kit-view':kitByPiece=el.dataset.mode==='piece';render();break;
    case 'kit-mode':{const k=kitById(id);await command({type:'kit_mode',kitId:id,assembled:!k.assembled},k.assembled?'Kit separado. Cada pieza sigue identificada.':'Kit rearmado y verificado.');break;}
    case 'select-kit':{const s=kitStatus(kitById(id));if(!s.complete)throw new Error('Hay piezas no disponibles en este kit.');s.parts.forEach(a=>selected.add(a.id));showPrepare();break;}
    case 'confirm-reserve':await command({type:'reserve',eventId:id,assetIds:[...selected]},'Piezas reservadas.',()=>{selected.clear();reserveTarget=null;location.hash='event/'+id;});break;
    case 'add-event-assets':reserveTarget=id;selected.clear();location.hash='inventory';toast('Selecciona las piezas disponibles para añadir al evento.');break;
    case 'scan-event':reserveTarget=id;location.hash='scan';break;
    case 'dispatch':confirmMovement('dispatch',id);break;case 'release':confirmMovement('release',id);break;case 'return':showReturn(id);break;
    case 'confirm-movement':await command({type:el.dataset.type,eventId:el.dataset.event,assetIds:JSON.parse(el.dataset.ids)},el.dataset.type==='dispatch'?'Salida física registrada.':'Piezas liberadas.',()=>{eventSelected.clear();render();});break;
    case 'assign-kit':{const a=byId(id);openModal('Asignar pieza a un kit',`<form data-form="assign-kit" data-id="${esc(id)}"><div class="modal-body"><p>${esc(a.name)}</p><label class="gap">Agrupación<select name="kitId"><option value="">Equipo individual · sin kit</option>${state.kits.map(k=>`<option value="${esc(k.id)}" ${k.id===a.kitId?'selected':''}>${esc(k.name)}</option>`).join('')}</select></label><div class="notice gap">${icon('info')}La identidad y el historial se conservan. Los kits afectados quedarán separados hasta verificar sus piezas.</div><div class="form-error gap"></div></div><div class="modal-foot">${btn('Cancelar','close')}<button class="btn primary">Guardar agrupación</button></div></form>`);break;}
    case 'maintenance-ready':case 'maintenance-start':openModal(action==='maintenance-ready'?'Confirmar revisión técnica':'Enviar equipo a revisión',`<form data-form="maintenance" data-id="${esc(id)}" data-ready="${action==='maintenance-ready'}"><div class="modal-body"><p>${esc(byId(id).name)}</p><label class="gap">Trabajo realizado / observaciones<textarea name="note" maxlength="1500" required></textarea></label><div class="form-error gap"></div></div><div class="modal-foot">${btn('Cancelar','close')}<button class="btn primary">Confirmar</button></div></form>`);break;
    case 'camera':await startCamera();break;case 'stop-camera':stopCamera();$('#cameraLabel').textContent='Cámara detenida';break;case 'scan-file':$('#scanFile').click();break;
    case 'select-scanned':selected.add(id);reserveTarget=null;location.hash=byId(id).kitId?'kit/'+byId(id).kitId:'inventory';toast('Pieza añadida a la selección.');break;
    case 'manifest':{const e=eventById(id);openModal('Manifiesto de carga',`<div class="modal-body"><div class="print-manifest"><h2>KLANDESTINO · ${esc(e.name)}</h2><p>${esc(e.place)} · ${esc(e.responsible)} · ${esc(e.vehicle)}</p><p>Salida: ${date(e.start,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})} · Retorno: ${date(e.end,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</p><table class="gap"><thead><tr><th>Equipo / código</th><th>Salida</th><th>Retorno</th></tr></thead><tbody>${e.items.filter(i=>i.status!=='released').map(it=>`<tr><td>${esc(byId(it.assetId)?.name)}<br><small>${esc(it.assetId)}</small></td><td>□</td><td>□</td></tr>`).join('')}</tbody></table><p class="gap">Entrega: ___________________ &nbsp; Recibe: ___________________</p></div></div>`,{wide:true,footer:btn(`${icon('print')} Imprimir`,'print')+btn('Cerrar','close')});break;}
    case 'print':window.print();break;case 'photo':{const m=state.movements.find(m=>m.id===id);if(m?.photo)openModal('Evidencia de devolución',`<div class="modal-body"><img class="photo-preview" style="max-height:65vh" src="${esc(m.photo)}" alt="${esc(m.summary)}"><p>${esc(m.note)}</p></div>`);break;}
    case 'csv':exportCSV();break;case 'backup':download('klandestino-respaldo.json',JSON.stringify({exportedAt:new Date().toISOString(),...state},null,2));break;
    case 'import-backup':$('#importBackup').click();break;
    case 'reset-demo':openModal('Reiniciar demostración',`<div class="modal-body"><p>Se restablecerá el inventario ficticio de este navegador. Puedes exportar una copia antes de continuar.</p></div>`,{footer:btn('Cancelar','close')+btn('Reiniciar demo','confirm-reset','','danger')});break;
    case 'confirm-reset':if(mode==='demo'){localStorage.removeItem(STORE_KEY);selected.clear();eventSelected.clear();reserveTarget=null;closeModal();await bootstrap();toast('Demo restablecida.');}break;
    case 'logout':await api('logout',{});await bootstrap();break;
    case 'users':{const result=await api('users');openModal('Equipo y permisos',`<div class="modal-body">${result.users.map(u=>`<div class="part-item"><div class="part-info"><b>${esc(u.name)}</b><small class="product-detail">${esc(u.email)}</small></div><span class="badge neutral">${esc(u.role)}</span></div>`).join('')}<form data-form="new-user" style="display:grid" class="gap"><h3>Crear usuario</h3><div class="form-grid gap"><label>Nombre<input name="name" required maxlength="120"></label><label>Correo<input type="email" name="email" required maxlength="190"></label><label>Contraseña inicial<input name="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"></label><label>Permiso<select name="role"><option value="operator">Encargado</option><option value="reader">Consulta</option><option value="admin">Administrador</option></select></label></div><div class="form-error gap"></div><button class="btn primary gap">Crear usuario</button></form></div>`);break;}
  }}catch(e){toast(e.message,true);}
});
document.addEventListener('input',e=>{if(e.target.id==='inventorySearch'){viewFilter=e.target.value;updateInventoryRows();}});
document.addEventListener('change',async e=>{const el=e.target;
  if(el.dataset.select){el.checked?selected.add(el.dataset.select):selected.delete(el.dataset.select);updateSelection();}
  if(el.dataset.eventSelect){el.checked?eventSelected.add(el.dataset.eventSelect):eventSelected.delete(el.dataset.eventSelect);const id=location.hash.split('/')[1];$('#eventActions').innerHTML=eventActions(eventById(id));}
  if(el.id==='categoryFilter'){categoryFilter=el.value;updateInventoryRows();}if(el.id==='statusFilter'){statusFilter=el.value;updateInventoryRows();}
  if(el.id==='selectAllInventory'){filteredAssets().filter(available).forEach(a=>el.checked?selected.add(a.id):selected.delete(a.id));updateSelection();}
  if(el.id==='selectAllEvent'){const event=eventById(location.hash.split('/')[1]);event.items.filter(i=>['out','missing','reserved'].includes(i.status)).forEach(i=>el.checked?eventSelected.add(i.assetId):eventSelected.delete(i.assetId));render();}
  if(el.id==='motionToggle'){document.body.dataset.motion=el.checked?'on':'off';localStorage.setItem('kb-motion',el.checked?'on':'off');}
  if(el.id==='returnPhoto')await compressPhoto(el.files[0]);if(el.id==='scanFile')await readImageQR(el.files[0]);
  if(el.id==='returnCondition')$('.modal textarea').required=el.value!=='ok';
  if(el.id==='importBackup'){try{const file=el.files[0];if(!file||file.size>3000000)throw new Error('Usa una copia JSON de menos de 3 MB.');const imported=JSON.parse(await file.text());if(imported.version!==1||!['assets','kits','events','movements'].every(k=>Array.isArray(imported[k]))||!Number.isInteger(imported.revision))throw new Error('La copia no tiene un formato válido.');if(!imported.assets.every(a=>typeof a.id==='string'&&typeof a.name==='string'&&statusNames[a.status])||!imported.kits.every(k=>Array.isArray(k.expectedIds))||!imported.events.every(v=>Array.isArray(v.items))||!imported.movements.every(v=>Array.isArray(v.assetIds)))throw new Error('La copia tiene registros incompletos.');openModal('Restaurar copia demo',`<div class="modal-body"><p>Reemplazará los datos demo de este navegador con ${imported.assets.length} equipos. Exporta tu copia actual si deseas conservarla.</p></div>`,{footer:btn('Cancelar','close')+btn('Restaurar','confirm-import','','primary')});const restore=()=>{state=imported;saveDemo();selected.clear();closeModal();render();toast('Copia demo restaurada.');};$('[data-action="confirm-import"]').addEventListener('click',restore,{once:true});}catch(err){toast(err.message,true);}}
});
document.addEventListener('submit',async e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();if(busy)return;const values=Object.fromEntries(new FormData(form)),type=form.dataset.form;try{
  if(type==='lookup'){lookup(values.code);return;}
  if(type==='asset'){await command({type:'create_asset',...values},'Equipo incorporado con código único.');return;}
  if(type==='kit'){await command({type:'create_kit',...values,assetIds:[...selected]},'Kit creado con las piezas seleccionadas.',()=>{selected.clear();location.hash='kit/'+state.kits.at(-1).id;});return;}
  if(type==='event'){await command({type:'create_event',...values,assetIds:[...selected]},'Evento creado y piezas reservadas.',()=>{const event=state.events.at(-1);selected.clear();eventSelected.clear();reserveTarget=null;location.hash='event/'+event.id;});return;}
  if(type==='return'){await command({type:'return',eventId:form.dataset.event,assetIds:JSON.parse(form.dataset.ids),...values,...(returnPhoto?{photo:returnPhoto}:{})},values.condition==='missing'?'Faltante registrado. La pieza sigue pendiente.':'Devolución registrada.',()=>{eventSelected.clear();render();});return;}
  if(type==='assign-kit'){await command({type:'assign_kit',assetId:form.dataset.id,kitId:values.kitId||null},'Agrupación de la pieza actualizada.');return;}
  if(type==='maintenance'){await command({type:'maintenance',assetIds:[form.dataset.id],ready:form.dataset.ready==='true',note:values.note},'Revisión técnica actualizada.');return;}
  const submit=$('button[type=submit],button:not([type])',form);if(submit)submit.disabled=true;
  try{
    if(type==='login'){await api('login',values);await bootstrap();}
    if(type==='setup'){await api('setup',{...values,seedDemo:values.seedDemo==='on'},{'X-Setup-Key':values.setupKey});await bootstrap();toast('Administrador creado. Ahora inicia sesión.');}
    if(type==='new-user'){await api('user_create',values);closeModal();toast('Usuario creado.');}
  }finally{if(submit)submit.disabled=false;}
}catch(err){const target=$('.form-error',form);if(target)target.textContent=err.message;else toast(err.message,true);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('.modal')){const elements=$$('button,input,select,textarea,a[href]',$('.modal')).filter(el=>!el.disabled&&el.offsetParent!==null);const first=elements[0],last=elements.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{stopCamera();if(!busy)closeModal();eventSelected=new Set(verifiedForEvent.get(location.hash.split('/')[1])||[]);render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('pagehide',stopCamera);
window.addEventListener('storage',e=>{if(mode==='demo'&&e.key===STORE_KEY&&!busy){try{const next=JSON.parse(e.newValue);if(next&&next.revision>state.revision){state=next;render();}}catch{}}});
setInterval(async()=>{if(mode!=='server'||document.hidden||busy||$('.modal'))return;try{const data=await api('bootstrap');if(data.state&&data.state.revision!==state.revision){state=data.state;render();}}catch{}},20000);
bootstrap();
